var maximumPopulation = function(logs) {
    const offset = 1950;
    const len = 2050 - 1950 + 1;
    let delta = new Array(len).fill(0);
    for (let log of logs) {
        delta[log[0] - offset] += 1;
        delta[log[1] - offset] -= 1;
    }
    let max = 0;
    let total = 0;
    let index = 0;
    for (let i = 0; i < len; i++) {
        total += delta[i];
        if (total > max) {
            max = total;
            index = i;
        }
    }
    return index + offset;
};

class Solution {
    public int maximumPopulation(int[][] logs) {
        int offset = 1950;
        int[] delta = new int[101];
        // 遍历每个人的出生和死亡年份
        for (int[] log : logs) {
            // 出生年份人数+1
            ++delta[log[0] - offset];
            // 死亡年份人数-1
            --delta[log[1] - offset];
        }

        // mx表示人口数量最大值，cur表示当前年份人口数量，res表示人口数量最大的年份-offset
        int mx = 0, cur = 0, res = 0;
        for (int i = 0; i < 101; ++i) {
            cur += delta[i];
            if (mx < cur) {
                mx = cur;
                res = i;
            }
        }
        return res + offset;
    }
}
